require_once __DIR__.'/helpers.php';
$id=(int)($_GET['id']??0);$stmt=$pdo->prepare("SELECT f.*,e.position,e.employee_code FROM operational_funds f LEFT JOIN employees e ON e.id=f.employee_id WHERE f.id=:id");$stmt->execute([':id'=>$id]);$fund=$stmt->fetch(PDO::FETCH_ASSOC);if(!$fund)redirect('pages/finance/operational_funds.php?error=Dana tidak ditemukan');
$stmt=$pdo->prepare("SELECT m.*,a.account_name,p.project_name FROM operational_fund_movements m LEFT JOIN finance_accounts a ON a.id=m.account_id LEFT JOIN projects p ON p.id=m.project_id WHERE m.fund_id=:id ORDER BY m.movement_date DESC,m.id DESC");$stmt->execute([':id'=>$id]);$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);
$pageTitle='Detail Dana Operasional - Nukari';require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';?>
<main class="main-content"><div class="page-header d-flex justify-content-between"><div><h1 class="fw-bold mb-1"><?= f_e($fund['person_name']); ?></h1><p class="text-muted mb-0"><?= f_e($fund['fund_code']); ?> · satu saldo berkelanjutan untuk PIC ini</p></div><a class="btn btn-outline-success" href="<?= base_url('pages/finance/operational_funds.php'); ?>">Kembali</a></div>
<div class="row g-3 mb-4"><?php foreach(['Diterima'=>$fund['total_received'],'Dipakai'=>$fund['total_used'],'Dikembalikan'=>$fund['total_returned'],'Saldo'=>$fund['current_balance']] as $label=>$amount): ?><div class="col-md-3"><div class="panel h-100"><div class="text-muted small"><?= $label; ?></div><div class="fs-5 fw-bold <?= $label==='Saldo'&&$amount<0?'text-danger':''; ?>"><?= rupiah($amount); ?></div></div></div><?php endforeach; ?></div>
<?php if((float)$fund['current_balance']<0): ?><div class="alert alert-danger rounded-4"><b>Saldo minus.</b> Perusahaan memiliki hutang <?= rupiah(abs($fund['current_balance'])); ?> kepada <?= f_e($fund['person_name']); ?>. Pemberian dana berikutnya otomatis mengurangi hutang ini terlebih dahulu.</div><?php endif; ?>
<div class="panel"><h5 class="fw-bold mb-3">Seluruh Mutasi</h5><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Tanggal</th><th>Jenis</th><th>Akun</th><th>Project</th><th>Keterangan</th><th class="text-end">Nominal</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= date('d M Y',strtotime($r['movement_date'])); ?></td><td><?= f_e(opfund_movement_label($r['movement_type'])); ?></td><td><?= f_e($r['account_name']?:'-'); ?></td><td><?= f_e($r['project_name']?:'-'); ?></td><td><?= f_e($r['description']?:'-'); ?></td><td class="text-end fw-bold"><?= rupiah($r['amount']); ?></td></tr><?php endforeach; ?></tbody></table></div></div></main><?php require_once __DIR__.'/../../includes/footer.php'; ?>
